"use client";

import { useState } from "react";
import { T } from "@/components/T";
import { EmptyState } from "@/components/states/EmptyState";
import { ErrorState } from "@/components/states/ErrorState";
import { Skeleton } from "@/components/states/Skeleton";
import { OfficerShell } from "@/components/shell/OfficerShell";
import { useCreateVendorInvoice, useVendorInvoices, useVendorOrders } from "@/lib/api/hooks";
import { useAppStore } from "@/lib/store";

type Invoice = { id: number; invoice_no: string; po_id: number; amount: number; status: string; paid_at?: string; utr?: string };
type Order = { id: number; po_code: string; amount: number; status: string };
export default function Page() {
  const invoices = useVendorInvoices(); const orders = useVendorOrders(); const create = useCreateVendorInvoice(); const [poId, setPoId] = useState(""); const [amount, setAmount] = useState(""); const showSuccess = useAppStore((s) => s.showSuccess); const showError = useAppStore((s) => s.showError); const rows = (invoices.data?.items ?? []) as Invoice[]; const accepted = ((orders.data?.items ?? []) as Order[]).filter((order) => ["accepted", "delivered"].includes(order.status));
  async function submit(event: React.FormEvent) { event.preventDefault(); try { await create.mutateAsync({ po_id: Number(poId), amount: Number(amount) }); setPoId(""); setAmount(""); showSuccess("Invoice submitted for review"); } catch (error) { showError(error instanceof Error ? error.message : "Invoice could not be submitted"); } }
  return <OfficerShell role="vendor"><main className="mx-auto max-w-6xl space-y-5 p-5"><header><p className="font-label-sm text-primary">VENDOR LEDGER</p><h1 className="mt-1 font-headline-md text-on-surface"><T gu="ઇન્વૉઇસ અને ચુકવણી" en="Invoices and payments" hi="चालान और भुगतान" /></h1></header>{orders.isLoading || invoices.isLoading ? <Skeleton rows={5} /> : orders.isError ? <ErrorState error={orders.error} onRetry={() => void orders.refetch()} /> : invoices.isError ? <ErrorState error={invoices.error} onRetry={() => void invoices.refetch()} /> : <><form onSubmit={(event) => void submit(event)} className="card grid gap-3 p-4 md:grid-cols-[1fr_1fr_auto]"><label className="text-sm">Accepted purchase order<select required value={poId} onChange={(event) => setPoId(event.target.value)} className="mt-1 h-10 w-full rounded-lg border border-outline-variant px-3"><option value="">Select order</option>{accepted.map((order) => <option key={order.id} value={order.id}>{order.po_code} — ₹{Number(order.amount ?? 0).toLocaleString("en-IN")}</option>)}</select></label><label className="text-sm">Invoice amount (₹)<input required min="1" type="number" value={amount} onChange={(event) => setAmount(event.target.value)} className="mt-1 h-10 w-full rounded-lg border border-outline-variant px-3" /></label><button disabled={create.isPending || !accepted.length} className="btn-primary self-end rounded-lg px-4 py-2 text-sm"><T gu="ઇન્વૉઇસ સબમિટ કરો" en="Submit invoice" hi="चालान जमा करें" /></button></form>{rows.length === 0 ? <EmptyState title="No invoices yet" description="Submit an invoice after your purchase order is accepted and the batch is received." /> : <div className="overflow-x-auto rounded-xl border border-outline-variant bg-surface-container-lowest"><table className="min-w-full text-left text-sm"><thead className="bg-surface-container-low text-xs uppercase text-on-surface-variant"><tr><th className="px-4 py-3">Invoice</th><th className="px-4 py-3">PO ID</th><th className="px-4 py-3">Amount</th><th className="px-4 py-3">Status</th><th className="px-4 py-3">UTR / paid date</th></tr></thead><tbody>{rows.map((row) => <tr key={row.id} className="border-t border-outline-variant/60"><td className="px-4 py-3 font-mono text-xs">{row.invoice_no}</td><td className="px-4 py-3">#{row.po_id}</td><td className="px-4 py-3">₹{Number(row.amount).toLocaleString("en-IN")}</td><td className="px-4 py-3 capitalize">{row.status}</td><td className="px-4 py-3 font-mono text-xs">{row.utr || row.paid_at || "Awaiting payment"}</td></tr>)}</tbody></table></div>}</>}</main></OfficerShell>;
}
